      hu: "Az Al-Khalifiyah Könyvtár Muharraq városában található, és Bahrein egyik legrégebbi kulturális intézménye. Az 1919-ben alapított könyvtárban több mint 50.000 kötetet őriznek, köztük ritka kéziratokat a 18. századból. A könyvtár épülete hagyományos bahreini építészeti stílusban épült, és 2013-ban felújították. A gyűjtemény különösen gazdag iszlám jogi szövegekben és helyi krónikákban.",
