    descriptionAdvanced: {
      de: "Das Alte Zollhaus in Manama, erbaut 1937, war der Hauptzollbahnhof für den Hafen von Bahrain. Das Gebäude im Art-Déco-Stil besteht aus lokalem Korallenstein und beherbergte Büros und Lagerräume. Es spielte eine Schlüsselrolle im Handel mit Perlen und Öl. Nach der Verlagerung des Hafens wurde es 1999 restauriert und in ein Museum umgewandelt, das die Zollgeschichte Bahrains zeigt. Das Dach bietet einen Panoramablick auf die Bucht.",
      hu: "A Régi Vámház Manamában 1937-ben épült, és a bahreini kikötő vámügyeit intézte. Az épület art deco stílusban készült, homlokzatán a bahreini címer látható. A vámház fontos szerepet játszott a gyöngykereskedelemben. 1999-ben felújították, és ma múzeumként működik, ahol vámügyi dokumentumok és történelmi áruk kiállítása látható. Az épület tetejéről kilátás nyílik a tengerre.",
      ro: "Vechea Vamă din Manama, construită în 1937, era sediul principal al vămii portuare din Bahrain. Clădirea în stil Art Deco, realizată din piatră de corali, a fost restaurată în 1999 și transformată în muzeu. Expozițiile includ documente vamale istorice, cântare și mostre de mărfuri comerciale. Vama a fost un punct central pentru comerțul cu perle și petrol. De pe acoperiș se poate admira golful Bahrainului.",
      en: "The Old Custom House in Manama, built in 1937, was the primary customs office for Bahrain's port. The Art Deco building, constructed from local coral stone, features a prominent clock tower and arched windows. It handled the lucrative pearl trade and later oil exports. After the port moved in the 1970s, the building fell into disuse until its restoration in 1999. Today, it operates as a museum showcasing customs history, with exhibits of weighing scales, shipping manifests, and merchant artifacts.",
    },
