      hu: "Janusan Bahrein északi részén található, és a Dilmun-korból (i.e. 2000 körül) származik. A lelőhely több mint 50 temetkezési halomból áll, amelyek némelyike 5 méter magas. A halmokban kőlapokból készült kamrák találhatók, bennük csontvázakkal és kerámiákkal. Janusan az UNESCO világörökség része. Az ásatások az 1980-as években zajlottak.",
      ro: "Situl Janusan, situat în nordul Bahrainului, datează din perioada Dilmun (cca. 2000 î.Hr.). Cuprinde peste 50 de movile funerare, unele de până la 5 metri înălțime. Movilele conțin camere din plăci de piatră, cu schelete și ceramică. Situl face parte din Patrimoniul Mondial UNESCO și reflectă ierarhia socială dilmunită. Săpăturile sistematice au început în anii 1980.",
