      de: "Al-Markh ist eine archäologische Stätte im Süden Bahrains aus der Bronzezeit (ca. 3000 v. Chr.). Sie umfasst Siedlungsreste und Gräber, die auf eine landwirtschaftliche Gemeinschaft hinweisen. Ausgrabungen haben Bewässerungskanäle und Getreidespeicher freigelegt, die auf fortschrittliche landwirtschaftliche Techniken hindeuten. Die Stätte enthält auch Feuerstellen und Kochgeschirr. Al-Markh ist wichtig für das Verständnis der frühen Sesshaftwerdung auf Bahrain.",
