      de: "Wadi al-Sail ist eine paläolithische Fundstätte im Südwesten Bahrains, die auf ca. 50.000 v. Chr. datiert wird. Hier wurden Steinwerkzeuge wie Faustkeile und Schaber gefunden, die von Jägern und Sammlern hinterlassen wurden. Die Stätte liegt in einem ausgetrockneten Flussbett und liefert Hinweise auf die früheste menschliche Besiedlung der Insel. Wadi al-Sail ist eine der wenigen paläolithischen Stätten auf der Arabischen Halbinsel und von großer wissenschaftlicher Bedeutung.",
      hu: "Wadi al-Sail Bahrein délnyugati részén található, és a paleolitikumba (i.e. 50.000 körül) tartozik. A lelőhelyen kőeszközöket találtak, például baltákat és kaparókat, amelyeket vadászó-gyűjtögető csoportok használtak. A helyszín egy kiszáradt folyómederben fekszik, és az emberi megtelepedés legkorábbi bizonyítékait adja Bahreinben. Wadi al-Sail az Arab-félsziget egyik kevés paleolit lelőhelye.",
      ro: "Wadi al-Sail este un sit paleolitic din sud-vestul Bahrainului, datat în jur de 50.000 î.Hr. Au fost găsite unelte de piatră, precum răzuitoare și vârfuri de lance, lăsate de vânători-culegători. Situl este situat într-o albie de râu uscată și oferă dovezi ale celei mai vechi ocupații umane a insulei. Este unul dintre puținele situri paleolitice din Peninsula Arabică.",
      en: "Wadi al-Sail is a Palaeolithic site in southwestern Bahrain, dating to approximately 50,000 BCE. It yielded flint tools such as hand axes and scrapers, indicating the presence of early hominins. The site, located in a dry wadi, provides evidence of seasonal occupation and tool-making traditions. It is one of the oldest archaeological sites in Bahrain and contributes to understanding human migration across the Arabian Peninsula.",
