    id: "bahrain-dilmun-pottery-kilns-history-v2",
    type: "industry",
    name: { de: "Dilmun Töpferöfen", hu: "Dilmun fazekas kemencék", ro: "Cuptoarele de olărit Dilmun", en: "Dilmun Pottery Kilns" },
    coords: [50.5252, 26.1755],
    description: {
      de: "Diese historischen Öfen zeigen die Fortdauer des Töpferhandwerks in Bahrain, das seit der Dilmun-Zeit eine wichtige Rolle im Handel spielte.",
      hu: "Ezek a történelmi kemencék a bahreini fazekasság folytonosságát mutatják, amely a Dilmun-korszak óta fontos szerepet játszott a kereskedelemben.",
      ro: "Aceste cuptoare istorice demonstrează continuitatea meșteșugului olăritului în Bahrain, care a jucat un rol important în comerț încă din epoca Dilmun.",
      en: "These historical kilns demonstrate the continuity of pottery craftsmanship in Bahrain, which has played a major role in trade since the Dilmun era.",
    },
    facts: {
      de: ["Jahrtausendealte Tradition", "Befindet sich im Töpferdorf A'ali", "Traditionelle Brenntechniken", "Nutzt lokalen Ton"],
      hu: ["Több évezredes hagyomány", "A'ali fazekasfaluban található", "Hagyományos égetési technikák", "Helyi agyagot használnak"],
      ro: ["Tradiție de milenii", "Situată în satul de olari A'ali", "Tehnici tradiționale de ardere", "Utilizează lut local"],
      en: ["Millennia-old tradition", "Located in the pottery village of A'ali", "Traditional wood-fired techniques", "Utilizes locally sourced clay"],
    },
    imageHint: "Dilmun pottery kilns A'ali Bahrain",
    descriptionAdvanced: {
      de: "Die Dilmun Pottery Kilns in der Nähe von Qal'at al-Bahrain sind Überreste einer bedeutenden Töpfereiindustrie aus der Dilmun-Zeit (ca. 2000 v. Chr.). Diese Brennöfen wurden zur Herstellung von Keramikgefäßen verwendet, die für den Handel im gesamten Persischen Golf wichtig waren. Die Öfen sind aus Lehmziegeln gebaut und weisen eine runde Form mit einem Durchmesser von etwa 2 Metern auf. Archäologische Ausgrabungen haben zahlreiche Tonscherben und Werkzeuge zutage gefördert, die auf eine Massenproduktion hindeuten. Die Dilmun-Zivilisation war bekannt für ihren Seehandel, und die Keramik war ein wichtiges Exportgut. Die Stätte bietet Einblicke in die technologischen Fähigkeiten der alten Bewohner Bahrains und ihre wirtschaftlichen Aktivitäten. Heute ist der Ort ein geschütztes archäologisches Gebiet und Teil des UNESCO-Weltkulturerbes Qal'at al-Bahrain.",
      hu: "A Dilmun fazekaskemencék Bahreinben, Qal'at al-Bahrain közelében, a Dilmun-korszakból (kb. i. e. 2000) származó kerámiagyártás maradványai. A vályogtéglából épült, kör alakú kemencék átmérője körülbelül 2 méter. Itt készítették a kereskedelmi céllal gyártott kerámiákat, amelyeket a Perzsa-öbölben forgalmaztak. Az ásatások során cseréptöredékek és szerszámok kerültek elő, utalva a tömegtermelésre. A Dilmun civilizáció híres volt tengeri kereskedelméről, és a kerámia fontos exportcikk volt. A lelőhely bepillantást enged az ókori lakosok technológiai képességeibe és gazdasági tevékenységébe. Ma a terület védett régészeti hely, Qal'at al-Bahrain UNESCO világörökségi részének része.",
      ro: "Cuptoarele de olărit Dilmun din Bahrain, situate lângă Qal'at al-Bahrain, sunt rămășițe ale unei industrii de ceramică din perioada Dilmun (cca. 2000 î.Hr.). Aceste cuptoare din cărămidă de noroi, de formă circulară, aveau un diametru de aproximativ 2 metri. Ele erau folosite pentru a produce vase ceramice destinate comerțului în Golful Persic. Săpăturile arheologice au scos la iveală fragmente de ceramică și unelte, indicând producția de masă. Civilizația Dilmun era renumită pentru comerțul maritim, iar ceramica era un bun de export important. Situl oferă perspective asupra capacităților tehnologice și activităților economice ale locuitorilor antici. Astăzi, zona este un sit arheologic protejat, parte a Patrimoniului Mondial UNESCO Qal'at al-Bahrain.",
      en: "The Dilmun Pottery Kilns near Qal'at al-Bahrain are remnants of a sophisticated ceramic industry dating to around 2000 BCE. These mudbrick kilns, circular in shape with a diameter of about 2 meters, were used for firing pottery. The site reveals evidence of mass production, with numerous sherds and tools found. Dilmun was a major trading hub in the Persian Gulf, and its pottery was widely exported. The kilns demonstrate advanced pyrotechnology and organization of labor. Protected as part of the UNESCO World Heritage site, they provide crucial insights into ancient Bahraini economy and craftsmanship.",
    },
    factsAdvanced: {
      de: ["Die Brennöfen stammen aus der Zeit um 2000 v. Chr.", "Sie haben einen Durchmesser von etwa 2 Metern.", "Die Öfen bestehen aus Lehmziegeln.", "Es wurden über 1000 Tonscherben gefunden.", "Die Dilmun-Keramik wurde bis nach Mesopotamien gehandelt.", "Die Stätte ist Teil des UNESCO-Weltkulturerbes Qal'at al-Bahrain."],
      hu: ["A kemencék i. e. 2000 körülről származnak.", "Átmérőjük körülbelül 2 méter.", "Vályogtéglából épültek.", "Több mint 1000 cseréptöredéket találtak.", "A Dilmun kerámiát Mezopotámiába is exportálták.", "A lelőhely a Qal'at al-Bahrain UNESCO világörökség része."],
      ro: ["Cuptoarele datează din jurul anului 2000 î.Hr.", "Au un diametru de aproximativ 2 metri.", "Construite din cărămidă de noroi.", "Peste 1000 de fragmente ceramice au fost descoperite.", "Ceramica Dilmun era exportată până în Mesopotamia.", "Situl face parte din patrimoniul UNESCO Qal'at al-Bahrain."],
      en: ["The kilns date to around 2000 BCE.", "They have a diameter of about 2 meters.", "Constructed from mudbricks.", "Over 1000 pottery sherds were discovered.", "Dilmun pottery was traded as far as Mesopotamia.", "The site is part of the Qal'at al-Bahrain UNESCO World Heritage."],
    },
