      hu: ["A hidat 1942-ben nyitották meg.", "Hossza 1,2 kilométer.", "Eredetileg két sávos volt, ma négy sávos.", "A legnagyobb fesztáv 50 méter.", "Összeköti Muharraq és Bahrein szigetét.", "Naponta több mint 50.000 jármű halad át rajta."],
      ro: ["Podul a fost deschis în 1942.", "Lungimea este de 1,2 kilometri.", "Inițial avea două benzi, acum patru.", "Deschiderea maximă este de 50 de metri.", "Leagă insulele Muharraq și Bahrain.", "Peste 50.000 de vehicule îl traversează zilnic."],
      en: ["The bridge opened in 1942.", "It is 1.2 kilometers long.", "Originally two-lane, now four-lane.", "The main span is 50 meters.", "It connects Muharraq and Bahrain islands.", "Over 50,000 vehicles cross daily."],
