    imageHint: "Al-Fadhel Minaret mosaic tiles Bahrain",
    descriptionAdvanced: {
      de: "Das Al-Fadhel Minarett in Manama ist ein Überbleibsel einer alten Moschee aus dem 14. Jahrhundert. Es ist eines der ältesten islamischen Bauwerke in Bahrain und zeigt die frühe Verbreitung des Islam in der Region. Das Minarett ist aus lokalem Stein und Korallenmörtel gebaut und hat eine Höhe von etwa 20 Metern. Seine schlanke Form und die geometrischen Verzierungen sind typisch für die islamische Architektur dieser Zeit. Das Minarett diente als Grundlage für die heutige Al-Fadhel-Moschee, die modernisiert wurde. Es ist ein wichtiges kulturelles Erbe und ein Symbol der religiösen Geschichte Bahrains. Besucher können die Umgebung erkunden, die auch andere historische Gebäude aus derselben Epoche umfasst.",
      hu: "Az Al-Fadhel minaret Manamában egy régi mecset maradványa a 14. századból. Bahrein egyik legrégebbi iszlám építménye, amely az iszlám korai elterjedését mutatja a régióban. A minaret helyi kőből és korallhabarcsból készült, magassága körülbelül 20 méter. Karcsú formája és geometrikus díszítése jellemző az akkori iszlám építészetre. A minaret adta az alapját a mai Al-Fadhel mecsetnek, amelyet modernizáltak. Fontos kulturális örökség és Bahrein vallástörténetének szimbóluma. A látogatók felfedezhetik a környék más történelmi épületeit is.",
      ro: "Minaretul Al-Fadhel din Manama este o rămășiță a unei vechi moschei din secolul al XIV-lea. Este una dintre cele mai vechi construcții islamice din Bahrain, ilustrând răspândirea timpurie a islamului în regiune. Minaretul este construit din piatră locală și mortar de corali, având o înălțime de aproximativ 20 de metri. Forma sa zveltă și decorațiunile geometrice sunt tipice arhitecturii islamice a vremii. Minaretul a servit ca bază pentru moscheea Al-Fadhel actuală, care a fost modernizată. Este o importantă moștenire culturală și un simbol al istoriei religioase a Bahrainului. Vizitatorii pot explora împrejurimile, care includ și alte clădiri istorice din aceeași perioadă.",
      en: "The Al-Fadhel Minaret in Manama is a remnant of a 14th-century mosque, making it one of Bahrain's oldest Islamic structures. Built from local stone and coral mortar, it stands about 20 meters tall. Its slender silhouette and geometric decorations reflect medieval Islamic architecture. The minaret forms part of the modern Al-Fadhel Mosque complex. It is a protected heritage site, offering insights into the early Islamic period in the Gulf. The surrounding area contains other historical buildings, making it a focal point for cultural tourism.",
    },
    factsAdvanced: {
      de: ["Das Minarett stammt aus dem 14. Jahrhundert.", "Es ist etwa 20 Meter hoch.", "Es besteht aus lokalem Stein und Korallenmörtel.", "Es wurde im 15. Jahrhundert restauriert.", "Das Minarett ist das einzige erhaltene Bauwerk der ursprünglichen Moschee.", "Es steht seit 1978 unter Denkmalschutz."],
      hu: ["A minaret a 14. századból származik.", "Magassága körülbelül 20 méter.", "Helyi kőből és korallhabarcsból készült.", "A 15. században felújították.", "A minaret az eredeti mecset egyetlen fennmaradt építménye.", "1978 óta műemléki védelem alatt áll."],
      ro: ["Minaretul datează din secolul al XIV-lea.", "Înălțimea sa este de aproximativ 20 de metri.", "Construit din piatră locală și mortar de corali.", "A fost restaurat în secolul al XV-lea.", "Minaretul este singura structură rămasă din moscheea originală.", "Este monument istoric din 1978."],
      en: ["The minaret dates from the 14th century.", "It is approximately 20 meters tall.", "Built from local stone and coral mortar.", "It was restored in the 15th century.", "The minaret is the only surviving structure of the original mosque.", "It has been a protected monument since 1978."],
    },
