      de: ["Die Gräber stammen aus der Zeit um 2000 v. Chr.", "Es gibt 15 erhaltene Hügelgräber.", "Die Hügel haben einen Durchmesser von bis zu 20 Metern.", "Sie sind bis zu 5 Meter hoch.", "Die Gräber wurden in den 1950er Jahren entdeckt.", "Einige Grabhügel sind Teil des UNESCO-Weltkulturerbes."],
      hu: ["A sírok i. e. 2000 körülről származnak.", "15 fennmaradt halomsír található.", "A halmok átmérője elérheti a 20 métert.", "Magasságuk akár 5 méter is lehet.", "A sírokat az 1950-es években fedezték fel.", "Néhány halomsír az UNESCO világörökség része."],
      ro: ["Mormintele datează din jurul anului 2000 î.Hr.", "Există 15 movile funerare conservate.", "Movilele au un diametru de până la 20 de metri.", "Au o înălțime de până la 5 metri.", "Mormintele au fost descoperite în anii 1950.", "Unele movile fac parte din patrimoniul UNESCO."],
      en: ["The graves date from around 2000 BCE.", "There are 15 preserved burial mounds.", "The mounds have a diameter of up to 20 meters.", "They are up to 5 meters high.", "The graves were discovered in the 1950s.", "Some mounds are part of the UNESCO World Heritage."],
